    valid_texts = set(n_choices)
    for version in "ABCD":
        # map question numbers back to texts via printed files to know each question's choice count
        content = (built["tmp"] / f"version_{version}.txt").read_text(encoding="utf-8")
        qnum_to_text = {}
        current_q = None
        for line in content.splitlines():
            m = re.match(r"^(\d+)\. (.+)$", line)
            if m:
                current_q = int(m.group(1))
                qnum_to_text[current_q] = m.group(2)
                continue
            if re.match(r"^\s+[a-z]\) ", line):
