import csv
import json
import re
import string
import subprocess
import sys

import pytest

WORKSPACE = "/workspace"


def run(cmd, cwd):
    return subprocess.run(cmd, capture_output=True, text=True, cwd=cwd)


@pytest.fixture(scope="module")
def built(tmp_path_factory):
    """Build exam versions with seed 3 and parse all outputs."""
    tmp = tmp_path_factory.mktemp("exam")
    result = run([sys.executable, f"{WORKSPACE}/versions.py", "--seed", "3",
                  "--versions", "4"], cwd=tmp)
    assert result.returncode == 0, result.stderr

    with open(tmp / "key.csv", encoding="utf-8", newline="") as f:
        rows = list(csv.DictReader(f))
    assert [r["version"] for r in rows[:1]] == ["version"] or True

    exam = json.load(open(f"{WORKSPACE}/exam.json", encoding="utf-8"))

    info = {"tmp": tmp, "rows": rows, "exam": exam,
            "letters": {}, "order": {}, "choice_counts": {}}

    for v in "ABCD":
        content = (tmp / f"version_{v}.txt").read_text(encoding="utf-8")
        order, counts = [], {}
        current = None
        for line in content.splitlines():
            m = re.match(r"^(\d+)\. (.+)$", line)
            if m:
                current = int(m.group(1))
                order.append((current, m.group(2)))
                counts[current] = 0
            elif re.match(r"^\s+[a-z]\) ", line) and current is not None:
                counts[current] += 1
        info["order"][v] = [text for _, text in order]
        info["letters"][v] = {int(r["question_number"]): r["correct_letter"]
                              for r in rows if r["version"] == v}
        info["choice_counts"][v] = counts
    return info


@pytest.mark.parametrize("version", list("ABCD"))
def test_perfect_student_scores_100(built, version):
    key = built["letters"][version]
    responses = ",".join(key[i] for i in sorted(key))
    result = run([sys.executable, f"{WORKSPACE}/grade.py",
                  "--version", version, "--responses", responses], cwd=built["tmp"])
    assert result.returncode == 0, result.stderr
    assert "100.0%" in result.stdout


def test_versions_a_and_b_differ_in_question_order(built):
    order_a, order_b = built["order"]["A"], built["order"]["B"]
    assert len(order_a) == len(order_b)
    assert len(order_a) >= 8
    assert any(a != b for a, b in zip(order_a, order_b)), \
        "versions A and B have identical question order"


def test_every_key_letter_within_choice_range(built):
    valid_texts = {q["text"]: len(q["choices"]) for q in built["exam"]["questions"]}
    n_questions = len(built["exam"]["questions"])
    for v in "ABCD":
        assert sorted(built["letters"][v]) == list(range(1, n_questions + 1)), \
            f"version {v} key does not cover every question exactly once"
        # printed choice count must match the source question's choice count
        for qnum, text in zip(sorted(built["letters"][v]), built["order"][v]):
            assert text in valid_texts, f"unknown question text in {v}: {text}"
            assert built["choice_counts"][v][qnum] == valid_texts[text]
        for qnum, letter in built["letters"][v].items():
            n = built["choice_counts"][v][qnum]
            assert letter in string.ascii_lowercase[:n], (
                f"{v} Q{qnum}: letter '{letter}' outside choice range a..{string.ascii_lowercase[n - 1]}"
            )


def test_wrong_response_length_exits_with_error(built):
    n = len(built["letters"]["B"])
    for bad in ([",".join(["a"] * (n - 1)) if n > 1 else "",
                 ",".join(["a"] * (n + 1))]):
        result = run([sys.executable, f"{WORKSPACE}/grade.py",
                      "--version", "B", "--responses", bad], cwd=built["tmp"])
        assert result.returncode != 0, f"should fail on length-{len(bad.split(','))} input"
        assert "expected" in result.stderr.lower()
        assert str(n) in result.stderr


